-		return -EOPNOTSUPP;
+	int ret;
+
+	ret = sbi_fwft_set(SBI_FWFT_PTE_AD_HW_UPDATING, 0, 0);
+	if (ret)
+		pr_warn("CPU%u failed to disable hardware PTE A/D updating: %d\n",
+			cpu, ret);
+
+	return 0;
